class Reverse {
  public void solve(char[] arr) {
    int l = 0, r = arr.length - 1;
    while (l < r) {
      char temp = arr[l];
      arr[l] = arr[r];
      arr[r] = temp;
      l++;
      r--;
    }
  }
}

